html{scroll-behavior:smooth}
body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.55 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
button,input,select{font:inherit}
button,a,input,select{touch-action:manipulation}
a{color:var(--green);text-underline-offset:4px}
button{cursor:pointer}
.button{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:11px 20px;border:1px solid transparent;border-radius:9px;font-weight:650;line-height:1.35;background:var(--green);color:white;text-decoration:none}
.button:hover:not(:disabled){background:#183c2d}
.button:disabled{background:#75877a}
.button.secondary{color:var(--green);background:var(--card);border-color:#8c9a8c}
.button.secondary:hover:not(:disabled){background:var(--soft-green)}
.button.full{width:100%;margin-top:16px}
.button.compact{min-height:38px;padding:8px 12px}
.brand small{display:block;font:500 .62rem system-ui,sans-serif;letter-spacing:.08em;margin-top:3px}
.brand-mark{display:flex;align-items:center;justify-content:center;color:transparent;flex-shrink:0}
.site-header nav{display:flex;gap:20px;flex-wrap:wrap}
.site-header nav a{font-size:.9rem;text-decoration:none;font-weight:600}
.site-header nav a[aria-current="page"]{color:var(--clay);text-decoration:underline;text-decoration-thickness:2px}
.account [data-testid="current-user"]{max-width:250px;overflow-wrap:anywhere}
.lead{color:var(--muted);max-width:620px;font-size:1.08rem}
.hero-note{display:none}
.quiet-note{background:#eeeee5;border-left:3px solid #a3af9b;padding:16px;font-size:.9rem;color:var(--muted)}
.auth-card label:not(:first-child){margin-top:18px}
.input-hint{font-size:.8rem;color:var(--muted);margin:10px 0;overflow-wrap:anywhere}
