.booking-placeholder h3{color:var(--ink)}
.place-symbol{font:2rem Georgia,serif;color:var(--clay);display:block;margin-bottom:16px}
.slot-heading span{font-size:.76rem;font-weight:400;color:var(--muted)}
.seat span{font-size:.75rem;line-height:1.5}
