.availability-key span{width:8px;height:8px;border-radius:50%;background:var(--green)}
.loading-dot{display:block;width:22px;height:22px;border:3px solid #d7dfcf;border-top-color:var(--green);border-radius:50%;margin:0 auto 20px;animation:turn 1s linear infinite}
@keyframes turn{to{transform:rotate(360deg)}}
.detail-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}
.detail-list{margin:20px 0}
.detail-list div{display:flex;justify-content:space-between;gap:16px;padding:12px 0;border-bottom:1px solid var(--line);overflow-wrap:anywhere}
.detail-list dt{color:var(--muted);font-size:.85rem}
.detail-list dd{margin:0;text-align:right;font-size:.9rem;min-width:0}
.reference.small{font-size:.95rem}
button:disabled{cursor:not-allowed}
:focus-visible{outline:3px solid #aa6b29;outline-offset:4px}
button,input,select{border-radius:9px}
input,select{width:100%;min-width:0;min-height:48px;padding:10px 12px;color:var(--ink);background:#fff;border:1px solid #8c9a8c}
